def classify(existing, incoming):
    new = changed = unchanged = 0
    for order_id, status in incoming:
        if order_id not in existing:
            new += 1
        elif existing[order_id] != status:
            changed += 1
        else:
            unchanged += 1
    return new, changed, unchanged

existing = {1: "paid", 2: "paid", 3: "failed"}
incoming = [(1, "paid"), (2, "refunded"), (3, "failed"), (4, "paid")]
print(classify(existing, incoming))

