CREATE TABLE api_orders (order_id integer PRIMARY KEY, status text NOT NULL);
CREATE TABLE stg_api_orders (order_id integer, status text);
INSERT INTO api_orders VALUES (1, 'paid'), (2, 'paid');
INSERT INTO stg_api_orders VALUES (1, 'paid'), (2, 'refunded'), (3, 'failed');
INSERT INTO api_orders SELECT order_id, status FROM stg_api_orders
ON CONFLICT (order_id) DO UPDATE SET status = EXCLUDED.status
WHERE api_orders.status IS DISTINCT FROM EXCLUDED.status;
SELECT order_id, status FROM api_orders ORDER BY order_id;
